"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-research-salience-rev1';O.mkdir(exist_ok=True)
SOURCE='reference/RESEARCH.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(856, 'SALIENCE-STATUS', 'Role/category, relevance, surprise and budgets qualified from authored inputs before interpretation correction.', 'Historical PARTIAL superseded only in later bounded pipeline; default independent does not select universal law.', ['GENERAL_ATTENTION_QUALIFICATION_2026_09_20.md', 'CAMPAIGN3_HISTORY_HQ010_CHECKPOINT.md']), (885, 'SALIENCE-CORRECTION', 'Three input flaws preserved: directly assigned roles, unattended flag, uncensored surprise.', 'Provenance slot mapping relocates authoring; does not prove source truthful, perceived or immune to misauthoring. Need relevance remains separate.', ['CAMPAIGN3_HISTORY_HQ007_CHECKPOINT.md', 'CAMPAIGN3_EPI_QUALIFICATION.md']), (931, 'SALIENCE-RESULTS', 'Role changes and surprise-only contrast produce reported salience changes; zero-attention differs from small relevance.', 'Argument fixture changes need and surprise together, not isolated need proof; later dedicated contrast required.63x describes reported raw ratio approximately.', ['CAMPAIGN3_HISTORY_HQ010_CHECKPOINT.md']), (968, 'SALIENCE-MATH', 'Exact product and three bounded budgets retain factors and exclude unperceived entries from denominator.', 'Transient recomputation explains no persistent normalization reuse; not blanket ban on quantization or cumulative cost.', ['CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md']), (1004, 'SALIENCE-INTEGRATION', 'Legacy opt-in equality and one-cycle weighted associations are bounded integration evidence.', 'One cycle does not establish arbitrary tag-count invariance. Participant/Target default corrected later; tests dated.', ['GENERAL_ATTENTION_QUALIFICATION_2026_09_20.md', 'CAMPAIGN3_HISTORY_HQ010_CHECKPOINT.md']), (1035, 'SALIENCE-ROUTING', 'World/perception/source hosting requirements and follow-up questions distinguished from measured parity.', 'Raw prediction error later replaced for bounds; saturation interaction later tested. Default budget remains comparison candidate.', ['CAMPAIGN3_EPI_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md']), (1118, 'INTERPRETATION', 'Fixed slot table, incidental residual attention and evidence-aware surprise replace independently authored downstream inputs.', 'Role cannot be mistyped claim limited to eliminated role field; wrong provenance still possible. Cause role only lawful when admitted, not omniscient causal truth.', ['CAMPAIGN3_HISTORY_HQ007_CHECKPOINT.md', 'CAMPAIGN3_EPI_QUALIFICATION.md']), (1201, 'INTERPRETATION-MATH', 'Attention1/5 divided by3 exactly1/15; one-sided residual bounded by absolute residual.', 'Exact attention ratio not exact bounded-response salience ratio. First-slot priority deterministic, not causal identification. Independent default preserves serious shared/hybrid comparisons.', ['GENERAL_ATTENTION_QUALIFICATION_2026_09_20.md', 'CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md']), (1244, 'INTERPRETATION-ARCHITECTURE', 'One provenance input consistently derives descriptor/connectivity; evidence classification separate from learning choice.', 'Safe classification must itself follow admitted evidence. Collapsed override not permission to merge world authority and character interpretation.139 dated tests not current whole suite.', ['CAMPAIGN3_EPI_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ007_CHECKPOINT.md']), (1282, 'INTERPRETATION-TRANSFER', 'Named producer/perception/classification obligations preserve character boundary in intended architecture.', 'Production hosting proposals not executed Vivarium parity. Later typed public contracts, not old source-truth provenance, govern cognition.', ['CAMPAIGN3_HISTORY_HQ009_CHECKPOINT.md', 'CAMPAIGN3_BIOLOGY_PUBLIC_QUALIFICATION.md']), (1314, 'INTERPRETATION-SUMMARY', 'Correction2 and saturation interaction supersede historical next-step routing in their declared scope.', 'General character-relative causal role must remain fallible; shared vocabulary does not establish every consumer law or universal necessity.', ['CAMPAIGN3_LEARN_QUALIFICATION.md', 'CAMPAIGN3_EPI_QUALIFICATION.md']), (1366, 'SATURATION-INTERACTION', 'Four end-to-end cases show equal safe saturation evidence/equal encoding, relevance contrast, informative bound and nonzero base at total saturation.', 'DERIVED scoped to fixed pipeline/horizon/query set; Case2 changes urgency and applied magnitude together. No universal absence of hedonic channel.', ['CAMPAIGN3_EPI_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md']), (1428, 'SATURATION-BOUNDARY', 'Overflow remains research truth; direct learning/encoding routes prohibited absent admitted sensing.', 'Independent experienced pleasure may be introduced lawfully and later biology does so; not relabelled Overflow or universal irrelevance of reward.', ['CAMPAIGN3_BIOLOGY_PUBLIC_QUALIFICATION.md', 'CAMPAIGN3_EPI_QUALIFICATION.md']), (1456, 'SATURATION-SUMMARY', 'Closing declared four comparisons leaves informative-bound approximation and alternative budgets intact.', 'Trace truth versus character evidence is durable; old phase gate and constructive minimalism superseded by current research method, not automatic Campaign3 exit.', ['CAMPAIGN3_HISTORY_HQ010_CHECKPOINT.md', 'CAMPAIGN3_LEARN_QUALIFICATION.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 856<=u['location']['startLine']<=1493:continue
  assert u['location']['endLine']<=1493
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(856,1494) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='HQ011 SALIENCE AND INTERPRETATION HISTORY REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-001','RO-C3-004','RO-C3-005','RO-C3-006','RO-C3-007','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-019','RO-C3-020','RO-C3-021'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Fourteen reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Reference RESEARCH1494 onward: rebaseline, identity and reason nuclei.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=1008+len(rows),freshBehavioralTests=0,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
